={{ JSON.stringify({
  system_instruction: {
    parts: [{
      text: "Anda adalah Spesialis Ekstraksi Data Accounts Payable (AP) senior untuk faktur B2B di Indonesia (mata uang Rupiah / IDR).\n\nTugas Anda adalah membaca dokumen PDF faktur yang dilampirkan dan mengekstrak seluruh field ke dalam JSON sesuai skema yang ditentukan.\n\nATURAN EKSTRAKSI KETAT:\n1. Mata Uang & Format Angka:\n   - Seluruh nilai moneter (unit_price, subtotal, tax_amount, grand_total) dan qty HARUS diekstrak sebagai angka murni (numeric) tanpa simbol \"Rp\", tanpa pemisah ribuan (titik/koma), dan tanpa teks tambahan.\n   - Ekstrak angka PERSIS seperti yang tercetak pada faktur. DILARANG mengoreksi, menghitung ulang, atau membenarkan kesalahan hitung PPN/total maupun selisih harga dari dokumen sumber.\n\n2. Penilaian `confidence_score` (WAJIB, rentang 0.0 sampai 1.0):\n   - 0.90 - 1.00: Dokumen tajam, tegak lurus, bebas noise, dan seluruh field vital (invoice_number, po_number, vendor_name, qty, unit_price, subtotal, tax_amount, grand_total) terbaca 100% jelas tanpa keraguan.\n   - 0.80 - 0.89: Terdapat sedikit artefak minor, namun seluruh angka dan nomor referensi vital masih dapat dibaca dengan pasti.\n   - DI BAWAH 0.80 (< 0.80) — WAJIB: Jika hasil scan miring, buram/blur, berbayang, terkena noise berat, terpotong, atau ada satu saja angka/nomor vital yang tidak terbaca jelas atau meragukan, Anda DILARANG KERAS mengarang, menebak, atau melakukan ekstrapolasi nilai. Anda WAJIB menurunkan `confidence_score` di bawah 0.80 (misalnya 0.35 - 0.75) dan menuliskan penyebab ketidakjelasan secara spesifik di `extraction_notes`.\n\n3. Kelengkapan & Kejujuran Data:\n   - Pastikan `invoice_number`, `po_number`, dan `vendor_name` diekstrak persis sesuai ejaan dan format pada faktur.\n   - Gunakan `extraction_notes` untuk mencatat kondisi fisik dokumen atau anomali pembacaan OCR (atau isi \"Dokumen terbaca jelas\" jika normal)."
    }]
  },
  contents: [{
    role: "user",
    parts: [
      { text: "Ekstrak seluruh field faktur B2B dari dokumen PDF terlampir sesuai skema JSON yang ditentukan." },
      { inline_data: { mime_type: "application/pdf", data: $json.pdf_base64 } }
    ]
  }],
  generationConfig: {
    temperature: 0,
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        invoice_number: { type: "STRING", description: "Nomor faktur resmi yang tertera pada dokumen" },
        po_number: { type: "STRING", description: "Nomor Purchase Order (PO) yang direferensikan pada faktur" },
        vendor_name: { type: "STRING", description: "Nama perusahaan vendor penerbit faktur" },
        item_name: { type: "STRING", description: "Nama atau deskripsi barang/jasa utama yang ditagihkan" },
        qty: { type: "NUMBER", description: "Kuantitas/jumlah unit barang atau jasa yang ditagihkan" },
        unit_price: { type: "NUMBER", description: "Harga satuan dalam IDR sebagai angka murni tanpa simbol mata uang" },
        subtotal: { type: "NUMBER", description: "Subtotal tagihan sebelum pajak/PPN dalam IDR" },
        tax_amount: { type: "NUMBER", description: "Nominal PPN/pajak yang tercetak pada faktur dalam IDR" },
        grand_total: { type: "NUMBER", description: "Total akhir tagihan (Grand Total) dalam IDR" },
        confidence_score: { type: "NUMBER", description: "Skor keyakinan pembacaan dokumen dari 0.0 hingga 1.0 (< 0.80 jika buram, miring, noise, atau angka vital tidak jelas)" },
        extraction_notes: { type: "STRING", description: "Catatan kualitas scan, bagian yang buram/miring/noise, atau catatan ekstraksi lainnya" }
      },
      required: [
        "invoice_number", "po_number", "vendor_name", "item_name", "qty",
        "unit_price", "subtotal", "tax_amount", "grand_total", "confidence_score", "extraction_notes"
      ]
    }
  }
}) }}

parameters.jsCode:
const CONFIDENCE_THRESHOLD = 0.85;
const TAX_RATE = 0.11;
const ROUNDING_TOLERANCE_IDR = 100;

function toFiniteNumber(value) {
  if (value === null || value === undefined || value === '') {
    return NaN;
  }
  const num = Number(value);
  return Number.isFinite(num) ? num : NaN;
}

function toTrimmedString(value) {
  if (value === null || value === undefined) {
    return '';
  }
  return String(value).trim();
}

function formatIDR(amount) {
  const sign = amount < 0 ? '-' : '';
  return `${sign}Rp${Math.abs(Math.round(amount)).toLocaleString('id-ID')}`;
}

function buildAuditResult(payload) {
  return {
    invoice_number: payload.invoice_number,
    po_number: payload.po_number,
    vendor_name: payload.vendor_name,
    invoiced_total: payload.invoiced_total,
    po_total: payload.po_total,
    variance: payload.variance,
    confidence_score: payload.confidence_score,
    audit_status: payload.audit_status,
    discrepancy_reason: payload.discrepancy_reason,
    requires_human_review: payload.requires_human_review,
    checked_rules: payload.checked_rules,
    audited_at: new Date().toISOString(),
  };
}

function auditInvoice(extractedInvoice, masterPOList = [], existingAuditLogs = []) {
  const invoice = extractedInvoice && typeof extractedInvoice === 'object' ? extractedInvoice : {};
  const poList = Array.isArray(masterPOList) ? masterPOList : [];
  const auditLogs = Array.isArray(existingAuditLogs) ? existingAuditLogs : [];

  const invoiceNumber = toTrimmedString(invoice.invoice_number) || null;
  const poNumber = toTrimmedString(invoice.po_number) || null;
  const vendorName = toTrimmedString(invoice.vendor_name) || null;

  const confidenceScore = toFiniteNumber(invoice.confidence_score);
  const invoicedTotal = toFiniteNumber(
    invoice.grand_total ?? invoice.billed_total ?? invoice.invoiced_total
  );
  const invoicedTax = toFiniteNumber(invoice.tax ?? invoice.tax_amount ?? invoice.billed_tax_11);
  const invoicedQty = toFiniteNumber(invoice.qty);
  const invoicedUnitPrice = toFiniteNumber(invoice.unit_price ?? invoice.billed_unit_price);

  const checkedRules = [];
  const basePayload = {
    invoice_number: invoiceNumber,
    po_number: poNumber,
    vendor_name: vendorName,
    invoiced_total: Number.isFinite(invoicedTotal) ? invoicedTotal : null,
    po_total: null,
    variance: null,
    confidence_score: Number.isFinite(confidenceScore) ? confidenceScore : null,
    checked_rules: checkedRules,
  };

  checkedRules.push('GATE_1_CONFIDENCE_THRESHOLD');
  if (!Number.isFinite(confidenceScore) || confidenceScore < CONFIDENCE_THRESHOLD) {
    const scoreDisplay = Number.isFinite(confidenceScore) ? confidenceScore : 'null/invalid';
    return buildAuditResult({
      ...basePayload,
      audit_status: 'HUMAN REVIEW',
      discrepancy_reason: `Confidence score OCR (${scoreDisplay}) berada di bawah ambang batas ${CONFIDENCE_THRESHOLD}.`,
      requires_human_review: true,
    });
  }

  checkedRules.push('GATE_2_DUPLICATE_CHECK');
  if (invoiceNumber && vendorName) {
    const invKey = invoiceNumber.toLowerCase();
    const vendorKey = vendorName.toLowerCase();
    const isDuplicate = auditLogs.some(
      (log) =>
        log &&
        toTrimmedString(log.invoice_number).toLowerCase() === invKey &&
        toTrimmedString(log.vendor_name).toLowerCase() === vendorKey
    );

    if (isDuplicate) {
      return buildAuditResult({
        ...basePayload,
        audit_status: 'HOLD - DUPLICATE',
        discrepancy_reason: `Duplicate billing terdeteksi untuk invoice "${invoiceNumber}" dari vendor "${vendorName}".`,
        requires_human_review: true,
      });
    }
  }

  checkedRules.push('GATE_3_PO_VALIDATION');
  const matchedPO = poNumber
    ? poList.find((po) => po && toTrimmedString(po.po_number).toLowerCase() === poNumber.toLowerCase())
    : null;

  if (!matchedPO) {
    return buildAuditResult({
      ...basePayload,
      audit_status: 'HOLD - INVALID PO',
      discrepancy_reason: `PO "${poNumber || 'kosong'}" tidak ditemukan di Master PO.`,
      requires_human_review: true,
    });
  }

  const poStatus = toTrimmedString(matchedPO.status).toUpperCase();
  if (poStatus !== 'OPEN') {
    return buildAuditResult({
      ...basePayload,
      audit_status: 'HOLD - INVALID PO',
      discrepancy_reason: `PO "${poNumber}" berstatus "${toTrimmedString(matchedPO.status) || 'UNKNOWN'}", bukan OPEN.`,
      requires_human_review: true,
    });
  }

  const poQty = toFiniteNumber(matchedPO.qty);
  const poUnitPrice = toFiniteNumber(matchedPO.unit_price);
  const poSubtotal = Number.isFinite(toFiniteNumber(matchedPO.expected_subtotal))
    ? toFiniteNumber(matchedPO.expected_subtotal)
    : poQty * poUnitPrice;
  const poTax = Number.isFinite(toFiniteNumber(matchedPO.expected_tax_11))
    ? toFiniteNumber(matchedPO.expected_tax_11)
    : Math.round(poSubtotal * TAX_RATE);
  const poTotal = Number.isFinite(toFiniteNumber(matchedPO.expected_total))
    ? toFiniteNumber(matchedPO.expected_total)
    : poSubtotal + poTax;

  basePayload.po_total = Number.isFinite(poTotal) ? poTotal : null;

  if (!Number.isFinite(invoicedQty) || !Number.isFinite(invoicedUnitPrice) || !Number.isFinite(invoicedTotal)) {
    return buildAuditResult({
      ...basePayload,
      audit_status: 'HUMAN REVIEW',
      discrepancy_reason: 'Field numerik invoice (qty, unit_price, atau grand_total) kosong atau tidak valid.',
      requires_human_review: true,
    });
  }

  checkedRules.push('GATE_4_DETERMINISTIC_MATH_TAX');
  const expectedSubtotal = invoicedQty * invoicedUnitPrice;
  const expectedTax = Math.round(expectedSubtotal * TAX_RATE);
  const expectedTotal = expectedSubtotal + expectedTax;

  const taxDiff = Number.isFinite(invoicedTax) ? invoicedTax - expectedTax : 0;
  const totalDiff = invoicedTotal - expectedTotal;

  if (
    (Number.isFinite(invoicedTax) && Math.abs(taxDiff) > ROUNDING_TOLERANCE_IDR) ||
    Math.abs(totalDiff) > ROUNDING_TOLERANCE_IDR
  ) {
    const nominalDiff = Math.abs(totalDiff) > ROUNDING_TOLERANCE_IDR ? totalDiff : taxDiff;
    return buildAuditResult({
      ...basePayload,
      variance: nominalDiff,
      audit_status: 'HOLD - TAX ERROR',
      discrepancy_reason:
        `Kesalahan perhitungan PPN 11% / Grand Total sebesar ${formatIDR(nominalDiff)} ` +
        `(tertagih ${formatIDR(invoicedTotal)}, seharusnya ${formatIDR(expectedTotal)}; ` +
        `PPN 11% seharusnya ${formatIDR(expectedTax)}).`,
      requires_human_review: true,
    });
  }

  checkedRules.push('GATE_5_PO_MATCHING_VARIANCE');
  const poVariance = invoicedTotal - poTotal;
  const hasQtyMismatch = invoicedQty !== poQty;
  const hasUnitPriceMismatch = Math.abs(invoicedUnitPrice - poUnitPrice) > ROUNDING_TOLERANCE_IDR;
  const hasTotalMismatch = Math.abs(poVariance) > ROUNDING_TOLERANCE_IDR;

  if (hasQtyMismatch || hasUnitPriceMismatch || hasTotalMismatch) {
    const reasons = [];
    if (hasQtyMismatch) {
      reasons.push(`qty tertagih ${invoicedQty} vs PO ${poQty}`);
    }
    if (hasUnitPriceMismatch) {
      reasons.push(`harga satuan tertagih ${formatIDR(invoicedUnitPrice)} vs PO ${formatIDR(poUnitPrice)}`);
    }
    if (hasTotalMismatch) {
      reasons.push(`selisih grand total ${formatIDR(poVariance)}`);
    }

    return buildAuditResult({
      ...basePayload,
      variance: poVariance,
      audit_status: 'HOLD - PRICE VARIANCE',
      discrepancy_reason: `Ketidaksesuaian terhadap PO "${poNumber}": ${reasons.join('; ')}.`,
      requires_human_review: true,
    });
  }

  return buildAuditResult({
    ...basePayload,
    variance: poVariance,
    audit_status: 'APPROVED',
    discrepancy_reason: null,
    requires_human_review: false,
  });
}

const geminiResponse = $('HTTP Request - Gemini Extraction').first().json || {};
const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let extractedInvoice = {};
try {
  extractedInvoice = typeof rawText === 'string' ? JSON.parse(rawText) : rawText;
} catch {
  extractedInvoice = { confidence_score: 0 };
}

const masterPOList = $('Read Master_PO').all().map((item) => item.json).filter((row) => row && row.po_number);
const existingAuditLogs = $('Read Invoice_Audit_Log').all().map((item) => item.json).filter((row) => row && row.invoice_number);

const auditResult = auditInvoice(extractedInvoice, masterPOList, existingAuditLogs);
return [{ json: auditResult }];

